"use client";
import { ArtemisScope } from "./artemis-scope";
import View3 from "./components/team/variants/04-marquee";
const variants = {"marquee":View3};
export interface ArtemisTeamProps { className?: string; variant?: "marquee"; }
export function ArtemisTeam({ className, variant = "marquee" }: ArtemisTeamProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View/></div></ArtemisScope>;}

"use client";
// @zeus-internal
import { artemisDemoAvatar } from "../../../lib/demo-avatar";
import { motion, useAnimationFrame, useMotionValue, useReducedMotion, type MotionValue } from "motion/react";
import { useEffect, useRef, type RefObject } from "react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
type Member = {
    slug: string;
    name: string;
    role: string;
    bio: string;
    photo: string;
};
const photo = artemisDemoAvatar;
const FOUNDING_MEMBER: Member = { slug: "jordan-blake", name: "Jordan Blake", role: "Founder & CEO", bio: "Sets the vision and keeps the bar high. Ex-design systems lead.", photo: photo("1531123897727-8f129e1688ce") };
const ROW_ONE: readonly Member[] = [
    FOUNDING_MEMBER,
    { slug: "jamie-reed", name: "Jamie Reed", role: "Head of Engineering", bio: "Owns the registry and runtime. Motion is a feature, not a finish.", photo: photo("1500648767791-00dcc994a43e") },
    { slug: "casey-ellis", name: "Casey Ellis", role: "Design Lead", bio: "Tunes every spring and curve until it feels physical.", photo: photo("1524504388940-b1c1722653e1") },
    { slug: "morgan-wells", name: "Morgan Wells", role: "Developer Advocate", bio: "Turns complex APIs into docs people enjoy reading.", photo: photo("1494790108377-be9c29b29330") },
    { slug: "riley-park", name: "Riley Park", role: "Staff Engineer", bio: "Performance obsessive who ships at 60fps or not at all.", photo: photo("1507003211169-0a1dd7228f2d") },
];
const ROW_TWO: readonly Member[] = [
    { slug: "quinn-avery", name: "Quinn Avery", role: "Product Manager", bio: "Keeps the roadmap honest and the scope ruthless.", photo: photo("1544005313-94ddf0286df2") },
    { slug: "cameron-shaw", name: "Cameron Shaw", role: "Motion Designer", bio: "Storyboards the interactions before a line of code is written.", photo: photo("1527980965255-d3b416303d12") },
    { slug: "robin-lane", name: "Robin Lane", role: "Infra Engineer", bio: "Keeps the edge fast and the deploys boring.", photo: photo("1506794778202-cad84cf45f1d") },
    { slug: "avery-stone", name: "Avery Stone", role: "Frontend Engineer", bio: "Lives in the component layer; allergic to layout shift.", photo: photo("1438761681033-6461ffad8d80") },
    { slug: "avery-lane", name: "Avery Lane", role: "Platform Engineer", bio: "Builds the tooling that makes everyone else faster.", photo: photo("1560250097-0b93528c311a") },
    FOUNDING_MEMBER,
];
const LINES: readonly (readonly string[])[] = [
    ["The", "humans", "behind"],
    ["every", "component."],
];
const WORD_HIDDEN = { opacity: 0, filter: "blur(10px)", y: "40%" };
const WORD_SHOWN = { opacity: 1, filter: "blur(0px)", y: "0%" };
const WORD_REDUCED = { opacity: 1 };
const WORD_STAGGER = 0.09;
const WORD_STAGGER_REDUCED = 0.027;
function wordTransition(index: number, reduce: boolean) {
    if (reduce)
        return { opacity: { duration: 0.25, ease: ARTEMIS_EASE_OUT, delay: index * WORD_STAGGER_REDUCED } } as const;
    const delay = index * WORD_STAGGER;
    return {
        opacity: { duration: 0.7, ease: ARTEMIS_EASE_OUT, delay },
        filter: { duration: 0.9, ease: ARTEMIS_EASE_OUT, delay },
        y: { type: "spring", duration: 0.86, bounce: 0, delay },
    } as const;
}
const SPEED_ONE = 26;
const SPEED_TWO = 20;
const VIEW_INSET = 0.1;
const LINK = "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:border-border art:hover:bg-primary/5 art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:size-8 art:bg-background art:text-muted-foreground art:hover:text-foreground art:rounded-full";
function MemberCard({ member, lift }: {
    member: Member;
    lift: boolean;
}) {
    const motionProps = lift ? { whileHover: { scale: 1.01 }, whileTap: { scale: 0.98 }, transition: ARTEMIS_SPRING_PRESS } : {};
    return (<div className="art:flex art:w-80 art:shrink-0 art:flex-col art:rounded-2xl art:border art:border-border art:bg-background art:p-4 art:transition-colors art:hover:border-foreground/20">
      <div className="art:flex art:items-center art:gap-3">
        <img src={member.photo} alt="" loading="lazy" className="art:size-11 art:shrink-0 art:rounded-full art:bg-muted art:object-cover art:object-[50%_25%]"/>
        <div className="art:min-w-0">
          <p className="art:truncate art:font-medium art:text-foreground art:text-sm">
            {member.name}
          </p>
          <p className="art:truncate art:text-muted-foreground art:text-xs">
            {member.role}
          </p>
        </div>
      </div>
      <p className="art:mt-3 art:text-pretty art:text-muted-foreground art:text-xs art:leading-5">
        {member.bio}
      </p>
      <div className="art:mt-3 art:flex art:items-center art:gap-1.5">
        <motion.a className={LINK} href={`#${member.slug}`} aria-label={`${member.name} website`} tabIndex={0} {...motionProps}>
          <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-globe art:size-3.5" aria-hidden="true">
            <circle cx="12" cy="12" r="10"/>
            <path d="M12 2a14.5 14.5 0 0 0 0 20 14.5 14.5 0 0 0 0-20"/>
            <path d="M2 12h20"/>
          </svg>
        </motion.a>
        <motion.a className={LINK} href={`#${member.slug}-social`} aria-label={`${member.name} social profile`} tabIndex={0} {...motionProps}>
          <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-at-sign art:size-3.5" aria-hidden="true">
            <circle cx="12" cy="12" r="4"/>
            <path d="M16 8v5a3 3 0 0 0 6 0v-1a10 10 0 1 0-4 8"/>
          </svg>
        </motion.a>
      </div>
    </div>);
}
function Row({ members, x, trackRef, lift }: {
    members: readonly Member[];
    x: MotionValue<number>;
    trackRef: RefObject<HTMLDivElement | null>;
    lift: boolean;
}) {
    const track = [...members, ...members];
    return (<div className="art:flex art:w-max">
      <motion.div ref={trackRef} className="art:flex art:w-max art:gap-4" style={{ x }}>
        {track.map((member, index) => (<MemberCard key={index} member={member} lift={lift}/>))}
      </motion.div>
    </div>);
}
export default function TeamMarquee() {
    const reduce = useReducedMotion() === true;
    const sectionRef = useRef<HTMLElement>(null);
    const oneRef = useRef<HTMLDivElement>(null);
    const twoRef = useRef<HTMLDivElement>(null);
    const xOne = useMotionValue(0);
    const xTwo = useMotionValue(0);
    const startedTwo = useRef(false);
    const hoveredRef = useRef(false);
    const visibleRef = useRef(false);
    useEffect(() => {
        const section = sectionRef.current;
        if (!section)
            return;
        const observer = new IntersectionObserver((entries) => {
            for (const entry of entries)
                visibleRef.current = entry.isIntersecting;
        }, { rootMargin: `-${VIEW_INSET * 100}% 0px -${VIEW_INSET * 100}% 0px` });
        observer.observe(section);
        return () => observer.disconnect();
    }, []);
    useAnimationFrame((_, frameDelta) => {
        const delta = frameDelta > 0 ? frameDelta : document.documentElement.classList.contains("dark") ? 1000 / 60 : 0;
        if (delta <= 0)
            return;
        if (reduce || !visibleRef.current || hoveredRef.current)
            return;
        const one = oneRef.current;
        const two = twoRef.current;
        if (!one || !two)
            return;
        const halfOne = one.offsetWidth / 2;
        const halfTwo = two.offsetWidth / 2;
        if (halfOne <= 0 || halfTwo <= 0)
            return;
        let nextOne = xOne.get() - (SPEED_ONE * delta) / 1000;
        if (nextOne <= -halfOne)
            nextOne += halfOne;
        xOne.set(nextOne);
        let nextTwo = (startedTwo.current ? xTwo.get() : -halfTwo) + (SPEED_TWO * delta) / 1000;
        startedTwo.current = true;
        if (nextTwo >= 0)
            nextTwo -= halfTwo;
        xTwo.set(nextTwo);
    });
    let wordIndex = 0;
    return (<>
      <div className="art:w-full">
        <section ref={sectionRef} className="art:w-full art:px-4 art:py-20 art:@min-[640px]/artemis:px-8">
          <div className="art:mx-auto art:w-full art:max-w-2xl art:text-center">
            <span className="art:inline-flex art:items-center art:rounded-full art:bg-muted art:px-3 art:py-1 art:font-medium art:text-muted-foreground art:text-xs art:shadow-[inset_0_1px_3px_rgba(0,0,0,0.06)]">
              {"Team"}
            </span>
            <h2 className="art:block art:mt-5 art:text-balance art:font-sans art:text-foreground art:text-4xl art:font-medium">
              {LINES.map((line) => (<span key={line.join(" ")} className="art:block">
                  {line.map((word, i) => {
                const index = wordIndex++;
                return (<motion.span key={word} className="art:inline-block art:will-change-transform" initial={WORD_HIDDEN} animate={reduce ? WORD_REDUCED : WORD_SHOWN} transition={wordTransition(index, reduce)}>
                        {word}
                        {i < line.length - 1 ? (<span className="art:inline-block art:w-[0.25em] art:overflow-hidden">
                            {"\u00A0"}
                          </span>) : null}
                      </motion.span>);
            })}
                </span>))}
            </h2>
            <p className="art:mx-auto art:mt-4 art:max-w-md art:text-pretty art:text-muted-foreground art:text-sm art:leading-7">
              {"A small, senior crew obsessed with motion, craft, and developer experience."}
            </p>
          </div>
          <div className="art:relative art:mt-14 art:flex art:flex-col art:gap-4 art:overflow-hidden art:[mask-image:linear-gradient(to_right,transparent,black_8%,black_92%,transparent)]" onMouseEnter={() => {
            hoveredRef.current = true;
        }} onMouseLeave={() => {
            hoveredRef.current = false;
        }}>
            <Row members={ROW_ONE} x={xOne} trackRef={oneRef} lift={!reduce}/>
            <Row members={ROW_TWO} x={xTwo} trackRef={twoRef} lift={!reduce}/>
          </div>
        </section>
      </div>
    </>);
}

// @zeus-internal
const avatars = ["/assets/artemis/a5badc559b706aa529b9.svg", "/assets/artemis/327d06eee6b741023403.svg", "/assets/artemis/83b960a1aaa67c851088.svg"];
export function artemisDemoAvatar(key: string) {
  const index = Array.from(key).reduce((sum, char) => sum + char.charCodeAt(0), 0);
  return avatars[index % avatars.length];
}
